      what: "“Mehedi 2.0” পাতা আপনার এআই কপির পরিচয়পত্র। উপরে তার নাম, অবস্থা (On, Paused, Off বা No key) আর এক লাইনে পরিচয়: সে এক্সপার্ট X26, X01 থেকে X25 এক্সপার্টদের প্রধান, আর সে যা লেখে সবকিছুতে তার নামের সঙ্গে (AI) লেখা থাকে। তার নিচে পাঁচটি সংখ্যা: Control-এ কয়টি ঘর Do, Ask ও Off; আজকের ও এ মাসের এআই খরচ; কয়টি বইয়ের টেস্ট পাস; আর কয়টি খসড়া ও অনুরোধ আপনার অপেক্ষায়। তারপর “What he never does” (তার স্থায়ী সীমা), “Tests” (প্রতিটি বইয়ের টেস্টের অবস্থা), “Teach” (আপনার নিয়ম, অর্থাৎ House Rules) আর “What he did last”।",
      why: "নতুন মার্চেন্ডাইজারকে যেমন বায়ারের নিয়ম শেখাতে হয়, Mehedi 2.0-কেও তেমনি শেখাতে হয়। ধরুন এক ইউরোপিয়ান বায়ারের সব পোলোতে প্ল্যাকেট 3 সেমি, বা আরেক বায়ারের কার্টনে সবসময় 12 পিস: “Teach a rule” দিয়ে একবার লিখে Approve করলে প্রতিটি কাজে সে এটি মানে, তার বইয়ের সাধারণ নিয়মের উপরে। আর এক নজরে দেখা যায় সে কতটা নিজে করতে পারে, কত খরচ করছে আর টেস্টে পাস করেছে কিনা; তাই কোনো কাজ তার হাতে ছাড়ার আগে বুঝে নিতে পারেন।",
