      why: "ধরুন আপনার হাউসে প্রতিটি পোলো শার্টের কস্টিং বায়ারকে পাঠানোর আগে একজন সিনিয়র দেখে নেন: ফ্যাব্রিকের দাম সাপ্লায়ারের কেজির কোটেশন থেকে এসেছে কিনা, CM ফ্যাক্টরির সঙ্গে ঠিক করা দামে কিনা, আর প্রফিট % দেওয়া আছে কিনা। এই চেকটি স্কিল হিসেবে X01 Senior Merchandiser-কে শেখালে, আর কয়েকটি উদাহরণ দিলে (যেমন CM খালি থাকা একটি শিট আর তার সঠিক উত্তর), এআই প্রতিবার একই নিয়মে দেখে। টেস্ট পাস না করা পর্যন্ত সে নিজে কিছু করে না, আর ভুল শেখালে আগের ভার্সনে এক চাপে ফেরা যায়।",
